import { useEffect } from 'react';
import { useFormContext } from 'react-hook-form';
import { useGetCstmrListQuery } from '~/entities/user/api/use-get-cstmr-list-query';
import { SuperAppCommandInbound } from '~/shared/api/dtos/enums';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { Select } from '~/shared/ui/selects';
import { CommandTooltip } from './command-tooltip';
import { useGenerateUserData } from '~/super-app-sample/hooks/use-generate-user-data';
import { NEW_USER, TEST_CASE_OPTIONS } from '~/super-app-sample/model/constants';
import { FormValues } from '~/super-app-sample/model/schema';

export const CommandSelect = () => {
  const { watch, setValue, trigger } = useFormContext<FormValues>();
  const command = watch('command');
  const selectCi = watch('selectCi');
  const { generateNewUserData } = useGenerateUserData(setValue);
  const { data: cstrList = [] } = useGetCstmrListQuery();
  const { openAlertDialog } = useAlertDialog();

  useEffect(() => {
    // 커맨드가 변경될 때마다 txCode 초기화하고 validation 실행
    setValue('txCode', '', { shouldValidate: true });

    // 지갑생성 커맨드가 선택되었을 때 새로운 사용자 데이터 생성
    if (command === SuperAppCommandInbound.지갑생성_요청) {
      openAlertDialog({
        message: `${"'슈퍼앱 지갑생성(C)' 커맨드는\n 단순 커맨드 테스트 목적으로,\n\n 정상적인 지갑 생성 Flow는\n\n '슈퍼앱 로그인(S)' 커맨드에서\n '신규 사용자 생성' 선택 후\n 진행 해야 합니다."}`,
      });
      generateNewUserData(cstrList);
    }

    // 로그인 커맨드이고 selectCi가 없을 때 신규 사용자 생성으로 세팅
    if (command === SuperAppCommandInbound.로그인 && !selectCi) {
      setValue('selectCi', NEW_USER);
    }

    // command가 변경될 때마다 form validation 실행
    trigger();
  }, [command, setValue, trigger, generateNewUserData, cstrList, selectCi, openAlertDialog]);

  return (
    <div className="flex w-full flex-row">
      <div className="flex-1">
        <Select
          classStr="shrink-0 "
          placeholder="command"
          labels={TEST_CASE_OPTIONS.map((opt) => opt.label)}
          values={TEST_CASE_OPTIONS.map((opt) => opt.value)}
          name="command"
          isErrorPaddingPresent={false}
        />
      </div>
      <CommandTooltip command={command} />
    </div>
  );
};
