import { z } from 'zod';
import { SuperAppCommandInbound, SuperAppCommandOutbound } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

export const formSchema = z
  .object({
    userCI: z.string().min(1, i18n.t('enterCI')),
    userId: z.string().min(1, i18n.t('enterUniversalUserId')),
    account: z.string().optional(),
    command: z.union([z.nativeEnum(SuperAppCommandInbound), z.nativeEnum(SuperAppCommandOutbound)]),
    superAppCallback: z.string(),
    txCode: z.string().optional(),
    selectCi: z.string().optional(),
  })
  .superRefine((data, ctx) => {
    if (data.command === SuperAppCommandInbound.앱to앱_결제요청) {
      if (!data.txCode) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: i18n.t('enterTxCode'),
          path: ['txCode'],
        });
      }
      if (!data.selectCi) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: '사용자를 선택해 주세요.',
          path: ['selectCi'],
        });
      }
    }
  });

export type FormValues = z.infer<typeof formSchema>;
