import { useEffect, useCallback } from 'react';
import { useFormContext } from 'react-hook-form';
import { useImmer } from 'use-immer';
import { useGetCstmrListQuery } from '~/entities/user/api/use-get-cstmr-list-query';
import i18n from '~/shared/i18n/i18n';
import { CommonTooltip } from './common-tooltip';
import { SelectFilter } from '~/super-app-sample/components/select-filter';
import { useGenerateUserData } from '~/super-app-sample/hooks/use-generate-user-data';
import { SELECTED_USER_KEY, NEW_USER } from '~/super-app-sample/model/constants';
import { FormValues } from '~/super-app-sample/model/schema';
import { buildUserSelectionValue, findUserBySelectionValue } from '~/super-app-sample/model/user-selection';

export const UserSelector = () => {
  const { setValue, watch } = useFormContext<FormValues>();
  const { data: cstrList = [] } = useGetCstmrListQuery();
  const [labels, setLabels] = useImmer<string[]>([]);
  const [values, setValues] = useImmer<string[]>([]);

  const { generateNewUserData, updateExistingUserData } = useGenerateUserData(setValue);

  const initializeUserData = useCallback(() => {
    if (!cstrList.length) return;

    const filterData = cstrList.filter((item) => !!item.ci);
    setLabels([
      '신규 사용자 생성',
      ...filterData.map((item) => item.koreanNm! + ':' + item.cstmrNo! + '; ' + item.acnutno),
    ]);
    setValues([NEW_USER, ...filterData.map(buildUserSelectionValue)]);

    return filterData;
  }, [cstrList, setLabels, setValues]);

  useEffect(() => {
    const filterData = initializeUserData();
    if (filterData) {
      const savedSelectionValue = localStorage.getItem(SELECTED_USER_KEY);
      if (savedSelectionValue && findUserBySelectionValue(filterData, savedSelectionValue)) {
        setValue('selectCi', savedSelectionValue);
      }
    }
  }, [initializeUserData, setValue]);

  useEffect(() => {
    const subscription = watch((value, { name }) => {
      if (name === 'selectCi') {
        const selectionValue = value.selectCi;
        if (selectionValue === NEW_USER) {
          generateNewUserData(cstrList);
        } else if (selectionValue) {
          const selectedUser = findUserBySelectionValue(cstrList, selectionValue);
          if (selectedUser) {
            updateExistingUserData(selectedUser, selectionValue);
          }
        }
      }
    });
    return () => subscription.unsubscribe();
  }, [watch, cstrList, generateNewUserData, updateExistingUserData]);

  return (
    <div className="flex flex-row">
      <div className="flex-1">
        <SelectFilter
          classStr="shrink-0"
          placeholder={i18n.t('user')}
          labels={labels}
          values={values}
          name="selectCi"
          isErrorPaddingPresent={false}
        />
      </div>
      <CommonTooltip
        content={'테스트용으로 가져오는 DB에 저장된 사용자 정보입니다. 선택 시 userId가 자동으로 입력됩니다.'}
        buttonId="user-help-button"
      />
    </div>
  );
};
