import { TempUserParams } from '~/entities/user/api/dtos/types';

const USER_SELECTION_DELIMITER = '::';

export const buildUserSelectionValue = (user: TempUserParams) =>
  [user.ci ?? '', user.cstmrNo ?? '', user.acnutno ?? ''].join(USER_SELECTION_DELIMITER);

export const findUserBySelectionValue = (users: TempUserParams[], selectionValue: string) =>
  users.find((user) => buildUserSelectionValue(user) === selectionValue);
