import { Fragment, useCallback, useEffect, useState } from 'react';
import { useFormContext } from 'react-hook-form';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';
import { BaseSelectList, LabelEvent, SelectOption, SelectProps } from '~/shared/ui/selects/base';
import { TextInput } from '~/shared/ui/text-input/text-input';

export const SelectFilter = ({ placeholder, name, option, labels, values, classStr, disabled }: SelectProps) => {
  const [isOpenBottomSheet, setIsOpenBottomSheet] = useState(false);
  const [options, setOptions] = useState<{ value: string; label: string }[]>([]);
  const [filterOptions, setFilterOptions] = useState<{ value: string; label: string }[]>([]);
  const handleCloseBottomSheet = () => {
    setIsOpenBottomSheet(false);
    if ((!value || value?.length < 0) && option?.required) {
      setError(name, { type: 'required', message: option?.required.toString() ?? null });
    }
  };

  const { register, setValue, clearErrors, watch, getValues, setError } = useFormContext();
  const value = watch(name);

  const defaultValue = getValues(name);
  const selectedValue = watch(name, defaultValue);
  const selectedLabel = labels[values.indexOf(selectedValue)];

  const onInputClick = (event: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    event.preventDefault();
    setIsOpenBottomSheet(true);
  };

  const onLabelChange = ({ event, option: selectedOption }: { event: LabelEvent; option: SelectOption<string> }) => {
    setValue(name, selectedOption.value);
    setIsOpenBottomSheet(false);
    clearErrors(name);
  };

  useEffect(() => {
    setOptions(
      values.map((itemValue, index) => ({
        value: itemValue,
        label: labels[index],
      })),
    );
    setFilterOptions(
      values.map((itemValue, index) => ({
        value: itemValue,
        label: labels[index],
      })),
    );
    if (value?.length > 0) {
      setValue(name, selectedValue);
    }
  }, [values]);

  const fnChange = useCallback(
    (s: string) => {
      const filterData = options.filter(
        (item) => item.value?.includes(s.toUpperCase()) || item.label?.includes(s.toUpperCase()),
      );
      setFilterOptions(filterData);
    },
    [options],
  );
  return (
    <Fragment>
      <TextInput
        label={placeholder}
        {...register(name)}
        readOnly
        onClick={(e) => !disabled && onInputClick(e)}
        displayLabel={selectedLabel}
        selectMode
        classStr={classStr}
        disabled={!!disabled}
        isErrorPaddingPresent={false}
      />
      <BottomSheet title={placeholder} open={isOpenBottomSheet} onClose={handleCloseBottomSheet}>
        <div className="relative block h-9 border-b border-[#000]/[.56]">
          <label className="absolute left-0 h-9 leading-9 transition-all duration-200" htmlFor={'search'}>
            사용자 검색
          </label>
          <input
            type="text"
            id="search"
            style={{ paddingLeft: '70px' }}
            className="h-[28px] w-full rounded-none pr-[19px] text-xl leading-7 tracking-[0]"
            onChange={(e) => fnChange(e.target.value)}
            placeholder="사용자 이름을 입력 해 주세요"
          />
        </div>
        <BaseSelectList
          options={filterOptions}
          selectedOption={selectedValue ? { value: selectedValue, label: selectedLabel } : undefined}
          onLabelChange={onLabelChange}
        />
      </BottomSheet>
    </Fragment>
  );
};
