import { Suspense } from '@suspensive/react';
import clsx from 'clsx';
import { FormProvider } from 'react-hook-form';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { SuperAppCommandInbound } from '~/shared/api/dtos/enums';
import { CommandSelect } from './components/command-select';
import { FormField } from './components/form-field';
import { PageTitle } from './components/page-title';
import { UserSelector } from './components/user-selector';
import { useSuperAppSamplePage } from './hooks/use-super-app-sample-page';

/**
 * [주의] 테스트 전용 데모 페이지
 * - 슈퍼앱 연동 인터페이스 검증용으로 생성됨
 * - 실제 서비스와 무관하며 추후 삭제 가능
 */
export const SuperAppSamplePage = () => {
  const { form, handleSubmit, handlePageReset } = useSuperAppSamplePage();
  const { watch } = form;
  const command = watch('command');

  return (
    <div>
      <PageTitle title="현재 페이지 : 슈퍼앱" />

      <h3 className="mt-8 text-lg">인터페이스 입력 값</h3>
      <Suspense fallback={<FullScreenLoading />}>
        <FormProvider {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="ipt-form-area" style={{ overflow: 'auto' }}>
            <CommandSelect />
            {command !== SuperAppCommandInbound.지갑생성_요청 && <UserSelector />}
            <FormField
              label={'userId'}
              name="userId"
              maxLength={18}
              tooltip={`은행의 통합아이디\n전자지갑에서는 cstmrNo 명칭으로 사용됨`}
            />
            <FormField label={'userCI'} name="userCI" tooltip="사용자 CI" />
            <FormField label={'account'} name="account" tooltip="계좌번호" />
            <FormField label={'superAppCallback'} name="superAppCallback" tooltip="슈퍼앱 복귀 콜백 URL" />
            {command === SuperAppCommandInbound.앱to앱_결제요청 && (
              <FormField label={'txCode'} name="txCode" tooltip="바우처 시스템에서 발급받은 txCode" />
            )}
            <div className="btn-area flex flex-row gap-2">
              <button className="btm-btn" type="button" onClick={handlePageReset}>
                초기화
              </button>
              <button className={clsx('btm-btn app')} type="submit">
                전자지갑으로 이동
              </button>
            </div>
          </form>
        </FormProvider>
      </Suspense>
    </div>
  );
};
