import { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { SuperAppCommandInbound, SuperAppCommandOutbound } from '~/shared/api/dtos/enums';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { generateUrl } from '~/shared/lib/utils/generate-url';
import { RsaOaep } from '~/shared/lib/utils/rsa-oaep';
import { PATHS } from '~/shared/routes/paths';

export const useSuperAppSampleHandler = () => {
  const { openAlertDialog } = useAlertDialog();
  const navigate = useNavigate();
  const { encryptText } = RsaOaep();

  const handleSuperAppCommand = useCallback(
    async (reqData: SuperAppEncData) => {
      //console.log('SuperApp Command Received:', reqData);

      try {
        let encryptedData: SuperAppEncData;

        switch (reqData.command) {
          case SuperAppCommandOutbound.슈퍼앱_지갑_생성_요청:
          case SuperAppCommandOutbound.슈퍼앱_신규가입:
            encryptedData = await encryptText({
              ...reqData,
              command: SuperAppCommandInbound.지갑생성_요청,
            });
            navigate(
              generateUrl({
                baseUrl: PATHS.intro,
                command: SuperAppCommandInbound.지갑생성_요청,
                encData: encryptedData.encData as string,
                signature: encryptedData.signature as string,
                superAppCallback: reqData.superAppCallback,
              }),
              { replace: true },
            );
            break;

          case SuperAppCommandOutbound.슈퍼앱_앱to앱_결제성공:
            openAlertDialog({
              title: '슈퍼앱_앱to앱_결제성공',
              message: reqData,
              onConfirmClick: () => {
                window.location.replace(PATHS.superAppSample);
              },
            });
            break;

          case SuperAppCommandOutbound.슈퍼앱_에러콜백:
            openAlertDialog({
              title: '슈퍼앱_에러콜백',
              message: reqData,
              onConfirmClick: () => {
                window.location.replace(PATHS.superAppSample);
              },
            });
            break;
          default:
            openAlertDialog({
              title: '처리되지 않은 아웃바운드 명령',
              message: reqData,
              onConfirmClick: () => {
                window.location.replace(PATHS.superAppSample);
              },
            });
            break;
        }
      } catch (error) {
        console.error(error);
        openAlertDialog({
          title: 'useSuperAppSampleHandler 에러',
          message: reqData,
          onConfirmClick: () => {
            window.location.replace(PATHS.superAppSample);
          },
        });
      }
    },
    [navigate, encryptText, openAlertDialog],
  );

  return { handleSuperAppCommand };
};
