import { useFormContext } from 'react-hook-form';
import { TextInput } from '~/shared/ui/text-input/text-input';
import { CommonTooltip } from './common-tooltip';
import type { FormValues } from '~/super-app-sample/model/schema';

export const FormField = ({
  label,
  name,
  tooltip,
  ...props
}: {
  label: string;
  name: keyof FormValues;
  tooltip?: string;
} & Omit<React.ComponentProps<typeof TextInput>, 'name' | 'onChange' | 'onBlur' | 'ref'>) => {
  const { register } = useFormContext<FormValues>();
  return (
    <div className="flex w-full flex-row">
      <div className="flex-1">
        <TextInput label={label} {...register(name)} {...props} isErrorPaddingPresent={false} />
      </div>
      {tooltip && <CommonTooltip content={tooltip} buttonId={`${name}-help-button`} />}
    </div>
  );
};
