import { v4 } from 'uuid';
import { TempUserParams } from '~/entities/user/api/dtos/types';
import { SuperAppData } from '~/shared/api/dtos/enums';

export const generateSuperAppData = (dataType: SuperAppData, existingData: TempUserParams[]): string => {
  for (let i = 0; i < 10; i++) {
    let generatedValue = '';

    switch (dataType) {
      case SuperAppData.CI:
        generatedValue = v4().replace(/-/g, '');
        if (!existingData.find((item) => item.ci === generatedValue)) {
          return generatedValue;
        }
        break;

      case SuperAppData.통합아이디:
        generatedValue = v4().replace(/-/g, '').substring(0, 18);
        if (!existingData.find((item) => item.cstmrNo === generatedValue)) {
          return generatedValue;
        }
        break;

      case SuperAppData.계좌번호:
        const randomValues = crypto.getRandomValues(new Uint32Array(2));
        generatedValue = (randomValues[0].toString() + randomValues[1].toString()).substring(0, 14);
        if (!existingData.find((item) => item.acnutno === generatedValue)) {
          return generatedValue;
        }
        break;
    }
  }

  throw new Error('Failed to generate unique value after 10 attempts');
};
